void PageAsyncWaiter::ClearPopup(
    std::string* out_input, bool* out_query_submitted) {
  base::RunLoop loop;
  proxy_->ClearPopup(
      base::BindOnce(
          [](base::RunLoop* loop,
             std::string* out_input
,
             bool* out_query_submitted
,
             const std::string& input,
             bool query_submitted) {*out_input = std::move(input);*out_query_submitted = std::move(query_submitted);
            loop->Quit();
          },
          &loop,
          out_input,
          out_query_submitted));
  loop.Run();
}








